11: const LAST_NAMES=['Silva','Santos','Oliveira','Costa','Pereira','Ferreira','Almeida','Gomes','Rodrigues','Souza','Lima','Carvalho','Ribeiro','Martínez','García','Fernández','González','Romero','Mendes','Barbosa','Moreira','López','Andrade','Cruz','Dias','Torres','Araujo','Pinto','Ramos','Vieira'];
