15: const KEY='touchline-careers-v1';let db=loadDB(),activeSlot=null,state=null,route='dashboard',rosterTab='all',marketTab='all',modal=null,matchLog=[];
16: function loadDB(){try{return JSON.parse(localStorage.getItem(KEY))||{saves:{},settings:{sound:true,matchLength:5}}}catch{return{saves:{},settings:{sound:true,matchLength:5}}}}
17: function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch(error){console.error('Falha ao salvar Touchline:',error);toast('Não foi possível salvar. Exporte sua carreira e libere espaço no navegador.',true);return false}}
18: function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
19: function money(n){let a=Math.abs(n);return a>=1e6?`€${(n/1e6).toFixed(1)}m`:a>=1000?`€${Math.round(n/1000)}k`:`€${n}`}
20: function initials(s){return s.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
21: function clubData(key){return LEAGUES[key]}
22: function createLeague(key){let league=LEAGUES[key];return league.clubs.map((c,i)=>({id:`${key}-${i}`,name:c[0],short:c[1],color:c[2],stadium:c[3],capacity:c[4],rep:c[5],budget:(c[5]*c[5]*9000),wage:(c[5]*c[5]*120),players:createRoster(c[0],c[5],i),pts:0,w:0,d:0,l:0,gf:0,ga:0,form:[]}))}
23: function createRoster(club,rep,seed){let arr=[];for(let i=0;i<18;i++){let pos=POS[i],base=rep-10+(i<11?4:0)+Math.round(Math.sin((i+seed)*4.7)*7),age=18+((i*7+seed*3)%17),ovr=Math.max(47,Math.min(89,base+Math.round(Math.random()*5))),potential=Math.max(ovr,Math.min(94,ovr+Math.round(Math.random()*14)));arr.push({id:`${seed}-${i}-${Math.random().toString(36).slice(2,6)}`,name:`${FIRST_NAMES[(i*3+seed*5)%FIRST_NAMES.length]} ${LAST_NAMES[(i*7+seed*2)%LAST_NAMES.length]}`,pos,age,ovr,potential,form:Math.round(5+Math.random()*3),fitness:85+Math.round(Math.random()*15),value:Math.round((ovr*ovr*120)*(age<22?1.35:age>31?.65:1)),wage:Math.round(ovr*ovr*2.7),goals:0,apps:0,starter:i<11})}return arr}
24: function schedule(teams=state.teams){let ids=teams.map(t=>t.id),rot=ids.slice(),rounds=[];if(rot.length%2)rot.push(null);let n=rot.length;for(let r=0;r<n-1;r++){let games=[];for(let i=0;i<n/2;i++){let a=rot[i],b=rot[n-1-i];if(a&&b){if(r%2)[a,b]=[b,a];games.push({home:a,away:b,played:false,score:null})}}rounds.push(games);rot.splice(1,0,rot.pop())}let second=rounds.map((g,r)=>g.map(x=>({home:x.away,away:x.home,played:false,score:null})));return rounds.concat(second)}
25: function newCareer(form){let key=form.league,teams=createLeague(key),team=teams.find(t=>t.name===form.club);let now=new Date();let today=`${form.year||2026}-07-01`;state={manager:{name:form.manager,nationality:form.nationality,age:+form.age,appearance:form.appearance,experience:form.experience,rep:form.experience==='Lenda'?64:form.experience==='Experiente'?48:form.experience==='Promissor'?34:22,popularity:36,licenses:form.experience==='Lenda'?3:form.experience==='Experiente'?2:1,history:[],titles:0,wins:0,draws:0,losses:0,salary:18000,club:team.name},club:team.id,league:key,teams,round:0,matchday:1,calendar:schedule(teams),date:today,season:2026,formation:'4-3-3',tactic:'Equilibrado',mentality:'Equilibrada',contract:{years:2,salary:18000},difficulty:form.difficulty,realism:form.realism,matchLength:+form.matchLength,budget:team.budget,news:[{date:today,type:'clube',title:`${team.name} apresenta ${form.manager}`,body:`O novo treinador inicia um projeto de ${form.experience.toLowerCase()} no ${team.name}. A expectativa da diretoria é uma temporada competitiva.`}],offers:[],messages:[],history:[],settings:{},lastMatch:null,transfers:[],sacked:false};state.roster=team.players;state.available=makeMarket(teams);state.lineup=team.players.slice(0,11).map(p=>p.id);state.objective=team.rep>82?'Brigar pelo título':team.rep>76?'Classificar para competição continental':'Terminar na metade de cima';state.contract.years=2;return state}
26: function makeMarket(teams){let all=[];teams.forEach(t=>t.players.forEach(p=>{if(Math.random()<.58)all.push({...p,club:t.name,clubId:t.id,price:Math.round(p.value*(.85+Math.random()*.55)),id:`m-${p.id}`} )}));return all.sort((a,b)=>b.ovr-a.ovr)}
27: function currentClub(){return state?.teams.find(t=>t.id===state.club)}
28: function nextGame(){if(!state)return null;for(let r=state.round;r<state.calendar.length;r++){let g=state.calendar[r].find(x=>x.home===state.club||x.away===state.club);if(g&&!g.played)return g}return null}
29: function opponentOf(g){let id=g.home===state.club?g.away:g.home;return state.teams.find(t=>t.id===id)}
30: function clubById(id){return state.teams.find(t=>t.id===id)}
31: function dateText(date=state?.date){return new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})}
32: function toast(msg,error=false){let root=document.getElementById('toast-root');root.innerHTML=`<div class="toast ${error?'error':''}">${esc(msg)}</div>`;setTimeout(()=>root.innerHTML='',2800)}
33: function save(){if(!state||!activeSlot)return;db.saves[activeSlot]={state,updated:new Date().toISOString()};persist()}
34: function startSave(form,slot){state=newCareer(form);activeSlot=slot;db.saves[slot]={state,updated:new Date().toISOString()};persist();route='dashboard';modal=null;render();toast('Carreira iniciada. Boa temporada!')}
35: function setRoute(r){route=r;modal=null;render()}
36: function rankTeams(){return [...state.teams].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
37: function shortDate(){return new Date(`${state.date}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}
38: function addDays(n){let d=new Date(`${state.date}T12:00:00`);d.setDate(d.getDate()+n);state.date=d.toISOString().slice(0,10)}
39: function playerById(id){return state.roster.find(p=>p.id===id)}
40: function teamPower(team){let players=team.players;let avg=players.slice(0,11).reduce((a,p)=>a+p.ovr,0)/11;return avg*.72+team.rep*.28}
41: function simScore(home,away){let diff=teamPower(home)-teamPower(away),homeAdv=home.id===state.club?2.3:1.9;let lamH=Math.max(.35,1.35+(diff+homeAdv)/16),lamA=Math.max(.3,1.15-(diff+homeAdv)/17);function poisson(l){let L=Math.exp(-l),k=0,p=1;do{k++;p*=Math.random()}while(p>L);return k-1}return[Math.min(6,poisson(lamH)),Math.min(6,poisson(lamA))]}
42: function applyResult(game,h,a){game.played=true;game.score=[h,a];let home=clubById(game.home),away=clubById(game.away);home.gf+=h;home.ga+=a;away.gf+=a;away.ga+=h;if(h>a){home.pts+=3;home.w++;away.l++;home.form.unshift('W');away.form.unshift('L')}else if(h<a){away.pts+=3;away.w++;home.l++;away.form.unshift('W');home.form.unshift('L')}else{home.pts++;away.pts++;home.d++;away.d++;home.form.unshift('D');away.form.unshift('D')}home.form=home.form.slice(0,5);away.form=away.form.slice(0,5)}
43: function logEvent(text){matchLog.unshift(text)}
44: function badge(team,cls=''){return `<span class="club-badge ${cls}" style="background:${esc(team.color)}">${esc(team.short)}</span>`}
45: function topbar(){let c=currentClub();return `<div class="topbar"><div class="crumb">TOUCHLINE <span style="color:#59665a"> / </span> <b>${esc(routeLabel())}</b></div><div class="top-actions"><span class="date-pill">◷ &nbsp;${dateText()}</span>${c?`<span class="cash-pill">${money(state.budget)}</span>`:''}<button class="icon-btn" onclick="openModal('settings')" aria-label="Configurações">⚙</button></div></div>`}
46: function routeLabel(){return ({dashboard:'Visão geral',squad:'Elenco',tactics:'Táticas',fixtures:'Calendário',table:'Classificação',market:'Transferências',inbox:'Central do clube',stats:'Estatísticas',editor:'Editor de elencos',settings:'Configurações'})[route]||'Football Career Manager'}
47: function sideNav(){return `<aside class="sidebar"><div class="brand"><div class="brandmark">⚽</div><div><strong>TOUCHLINE</strong><small>CAREER MANAGER</small></div></div><div class="nav-label">CLUBE</div><nav class="nav">${NAV.map(([id,ico,label])=>`<button class="${route===id?'active':''}" onclick="setRoute('${id}')"><span class="ico">${ico}</span>${label}</button>`).join('')}</nav><div class="nav-label" style="margin-top:19px">GERAL</div><nav class="nav"><button class="${route==='stats'?'active':''}" onclick="setRoute('stats')"><span class="ico">◫</span>Estatísticas</button><button onclick="showCareerMenu()"><span class="ico">↶</span>Trocar carreira</button></nav><div class="side-bottom"><div class="manager-mini"><div class="avatar">${state?esc(initials(state.manager.name)):'?'}</div><div><b>${state?esc(state.manager.name):'Sem treinador'}</b><small>${state?esc(currentClub()?.name||'Sem clube'):'Crie uma carreira'}</small></div></div></div></aside>`}
48: function header(title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${esc(currentClub()?.name||'TOUCHLINE MANAGER')}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
49: function dashboard(){let c=currentClub(),game=nextGame(),opp=game?opponentOf(game):null,home=game?.home===state.club,rank=rankTeams(),place=rank.findIndex(t=>t.id===state.club)+1,played=c.w+c.d+c.l,playedGames=state.calendar.filter(r=>r.some(g=>g.played)).length;return `${header('Visão geral',`Temporada ${state.season} · ${state.league.split('|')[1]} · ${playedGames} rodadas disputadas`)}<section class="hero"><div class="hero-content"><div class="eyebrow">PRÓXIMO DESAFIO · RODADA ${state.matchday}</div><h2>${game?'Dia de jogo. Vamos, '+esc(c.name)+'.':'A temporada chegou ao fim.'}</h2><p>${game?`Prepare a equipe para ${home?'receber':'visitar'} ${esc(opp.name)}. A torcida espera uma grande atuação.`:'Revise seus resultados e prepare o próximo ano.'}</p>${game?`<div class="next-match"><button class="btn btn-primary" onclick="playMatch()">JOGAR PARTIDA &nbsp;→</button><span class="tag">${home?'CASA':'FORA'} · ${esc(opp.name)}</span></div>`:`<button class="btn btn-primary" onclick="advanceSeason()">COMEÇAR NOVA TEMPORADA</button>`}</div></section><div class="stats-row"><div class="stat-card"><div class="stat-label">POSIÇÃO NA LIGA</div><div class="stat-value">${place}<span style="font-size:12px;color:#859185">º / ${state.teams.length}</span></div><div class="stat-note good">${c.pts} pontos</div></div><div class="stat-card"><div class="stat-label">CAMPANHA</div><div class="stat-value">${c.w}<span style="color:#728073">-${c.d}-${c.l}</span></div><div class="stat-note">${played} partidas</div></div><div class="stat-card"><div class="stat-label">SALDO DE GOLS</div><div class="stat-value">${c.gf-c.ga>0?'+':''}${c.gf-c.ga}</div><div class="stat-note">${c.gf} marcados · ${c.ga} sofridos</div></div><div class="stat-card"><div class="stat-label">REPUTAÇÃO</div><div class="stat-value">${state.manager.rep}<span style="font-size:12px;color:#859185"> / 100</span></div><div class="stat-note good">${state.manager.popularity}% popularidade</div></div></div><div class="grid grid-2"><di... (line truncated to 2000 chars)
50: function leagueTable(teams,compact=false){let rank=rankTeams();return `<div class="table-wrap"><table class="table"><thead><tr><th>Clube</th><th>J</th><th>V</th><th>E</th><th>D</th><th>SG</th><th>PTS</th>${compact?'':'<th>Forma</th>'}</tr></thead><tbody>${teams.map(t=>`<tr><td><span class="club-cell"><span class="position">${rank.indexOf(t)+1}</span>${badge(t,'sm')}<span>${esc(t.name)}</span>${t.id===state.club?'<span class="tag green">VOCÊ</span>':''}</span></td><td>${t.w+t.d+t.l}</td><td>${t.w}</td><td>${t.d}</td><td>${t.l}</td><td>${t.gf-t.ga>0?'+':''}${t.gf-t.ga}</td><td><b>${t.pts}</b></td>${compact?'':`<td><span class="form-dots">${(t.form.length?t.form:['-','-','-','-','-']).map(x=>`<span class="form-dot ${x==='W'?'w':x==='D'?'d':x==='L'?'l':''}">${x}</span>`).join('')}</span></td>`}</tr>`).join('')}</tbody></table></div>`}
51: function upcomingFixtures(n=8){let matches=[];state.calendar.forEach((round,i)=>round.forEach(g=>{if((g.home===state.club||g.away===state.club)&&!g.played)matches.push({g,i})}));return matches.slice(0,n).map(({g,i})=>{let opponent=opponentOf(g);return `<div class="fixture"><div class="fixture-date">ROD. ${i+1}<br>${i===state.round?'PRÓXIMA':'+'+(i-state.round)+' sem'}</div><div class="fixture-clubs">${g.home===state.club?badge(currentClub(),'sm'):badge(opponent,'sm')}<b>${g.home===state.club?esc(currentClub().name):esc(opponent.name)}</b><span style="color:#748174">×</span><b>${g.away===state.club?esc(currentClub().name):esc(opponent.name)}</b>${g.away===state.club?badge(currentClub(),'sm'):badge(opponent,'sm')}</div><span class="tag">${g.home===state.club?'CASA':'FORA'}</span></div>`}).join('')||'<div class="empty" style="padding:20px">Nenhum jogo pendente.</div>'}
