function leagueTable(teams,compact=false){let rank=rankTeams();return `<div class="table-wrap"><table class="table"><thead><tr><th>Clube</th><th>J</th><th>V</th><th>E</th><th>D</th><th>SG</th><th>PTS</th>${compact?'':'<th>Forma</th>'}</tr></thead><tbody>${teams.map(t=>`<tr><td><span class="club-cell"><span class="position">${rank.indexOf(t)+1}</span>${badge(t,'sm')}<span>${esc(t.name)}</span>${t.id===state.club?'<span class="tag green">VOCÊ</span>':''}</span></td><td>${t.w+t.d+t.l}</td><td>${t.w}</td><td>${t.d}</td><td>${t.l}</td><td>${t.gf-t.ga>0?'+':''}${t.gf-t.ga}</td><td><b>${t.pts}</b></td>${compact?'':`<td><span class="form-dots">${(t.form.length?t.form:['-','-','-','-','-']).map(x=>`<span class="form-dot ${x==='W'?'w':x==='D'?'d':x==='L'?'l':''}">${x}</span>`).join('')}</span></td>`}</tr>`).join('')}</tbody></table></div>`}
function upcomingFixtures(n=8){let matches=[];state.calendar.forEach((round,i)=>round.forEach(g=>{if((g.home===state.club||g.away===state.club)&&!g.played)matches.push({g,i})}));return matches.slice(0,n).map(({g,i})=>{let opponent=opponentOf(g);return `<div class="fixture"><div class="fixture-date">ROD. ${i+1}<br>${i===state.round?'PRÓXIMA':'+'+(i-state.round)+' sem'}</div><div class="fixture-clubs">${g.home===state.club?badge(currentClub(),'sm'):badge(opponent,'sm')}<b>${g.home===state.club?esc(currentClub().name):esc(opponent.name)}</b><span style="color:#748174">×</span><b>${g.away===state.club?esc(currentClub().name):esc(opponent.name)}</b>${g.away===state.club?badge(currentClub(),'sm'):badge(opponent,'sm')}</div><span class="tag">${g.home===state.club?'CASA':'FORA'}</span></div>`}).join('')||'<div class="empty" style="padding:20px">Nenhum jogo pendente.</div>'}
function squadPage(){let positions=['GOL','ZAG','LD','LE','VOL','MC','MEI','PD','PE','ATA'];let filtered=state.roster.filter(p=>rosterTab==='all'||p.pos===rosterTab).sort((a,b)=>b.ovr-a.ovr);return `${header('Elenco',`${state.roster.length} atletas · Folha salarial ${money(state.roster.reduce((s,p)=>s+p.wage,0))}`,`<button class="btn btn-primary" onclick="setRoute('tactics')">MONTAR TIME →</button>`)}<div class="page-tabs"><button class="tab ${rosterTab==='all'?'active':''}" onclick="rosterTab='all';render()">Todos (${state.roster.length})</button>${positions.map(pos=>`<button class="tab ${rosterTab===pos?'active':''}" onclick="rosterTab='${pos}';render()">${pos} (${state.roster.filter(p=>p.pos===pos).length})</button>`).join('')}</div><div class="card"><div class="card-head"><h2>Jogadores</h2><span class="tag">ELENCO PRINCIPAL</span></div><div class="player-row header"><span>POS</span><span>JOGADOR</span><span>IDADE</span><span>GER</span><span>VALOR</span><span class="hide-mobile">CONTRATO</span><span class="hide-mobile">STATUS</span></div>${filtered.map(p=>`<div class="player-row"><span class="tag">${p.pos}</span><div><div class="player-name">${esc(p.name)}</div><div class="player-meta">${p.apps} partidas · ${p.goals} gols</div></div><span>${p.age}</span><span class="rating">${p.ovr}</span><span>${money(p.value)}</span><span class="hide-mobile">${money(p.wage)}/sem</span><button class="btn ${state.lineup.includes(p.id)?'btn-primary':''}" style="padding:6px 8px;font-size:9px" onclick="toggleStarter('${p.id}')">${state.lineup.includes(p.id)?'TITULAR':'RESERVA'}</button></div>`).join('')||'<div class="empty">Nenhum atleta nesta posição.</div>'}</div><div class="grid grid-3" style="margin-top:15px"><div class="stat-card"><div class="stat-label">MÉDIA DO ELENCO</div><div class="stat-value">${Math.round(state.roster.reduce((a,p)=>a+p.ovr,0)/state.roster.length)}</div><div class="stat-note">Overall geral</div></div><div class="stat-card"><div class="stat-label">VALOR DO ELENCO</div><div class="stat-value">${money(state.roster.reduce((a,p)=>a+p.value,0))}</div><div class="stat-note">Estimativa de mercado</div></div><div class="stat-card"><div class="stat-label">FOLHA SALARIAL</div><div class="stat-value">${money(state.roster.reduce((a,p)=>a+p.wage,0))}</div><div class="stat-note">Por semana</div></div></div>`}
function toggleStarter(id){let p=playerById(id);if(state.lineup.includes(id)){if(state.lineup.length<=7)return toast('Mantenha pelo menos 7 jogadores na equipe.',true);state.lineup=state.lineup.filter(x=>x!==id);p.starter=false}else{if(state.lineup.length>=11)return toast('A equipe titular já tem 11 jogadores.',true);state.lineup.push(id);p.starter=true}save();render()}
function tacticsPage(){let groups=Object.entries(FORMATIONS),lineup=state.lineup.map(playerById).filter(Boolean);let rows=state.formation.split('-').map(x=>+x);let byLines=[];let cursor=0;rows.forEach((n,idx)=>{let picks=lineup.slice(cursor,cursor+n);cursor+=n;byLines.push(picks)});let bench=state.roster.filter(p=>!state.lineup.includes(p.id));return `${header('Táticas','Escolha a formação e a abordagem para sua equipe.',`<button class="btn btn-primary" onclick="save();toast('Táticas salvas.')">SALVAR TÁTICAS</button>`)}<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Campo tático</h2><span class="tag green">${state.formation}</span></div><div class="pitch"><div class="pitch-line">${byLines.map((line,idx)=>`<div class="pitch-row">${line.map(p=>`<div class="pitch-player" onclick="openPlayer('${p.id}')"><div class="pitch-shirt">${p.pos}</div><small>${esc(p.name.split(' ').slice(-1)[0])}</small><em>${p.ovr} GER</em></div>`).join('')||'<span class="tag">Vazio</span>'}</div>`).join('')}</div></div><p class="stat-note" style="margin-top:12px">Toque em um jogador para ver seus detalhes. A equipe titular é definida no menu Elenco.</p></div><div class="card"><div class="card-head"><h2>Plano de jogo</h2></div><div class="field"><label>FORMAÇÃO</label><div class="page-tabs">${groups.map(([f])=>`<button class="tab ${state.formation===f?'active':''}" onclick="state.formation='${f}';save();render()">${f}</button>`).join('')}</div></div><div class="field" style="margin-top:15px"><label>ESTILO DE JOGO</label><select onchange="state.tactic=this.value;save()">${['Equilibrado','Posse de bola','Contra-ataque','Pressão alta','Jogo direto'].map(x=>`<option ${state.tactic===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="margin-top:15px"><label>MENTALIDADE</label><select onchange="state.mentality=this.value;save()">${['Defensiva','Equilibrada','Ofensiva','Muito ofensiva'].map(x=>`<option ${state.mentality===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="card" style="padding:13px;margin-top:18px;background:#111a13"><div class="card-head" style="margin-bottom:7px"><h2 style="font-size:13px">Força da equipe</h2><b class="rating">${Math.round(lineup.reduce((a,p)=>a+p.ovr,0)/Math.max(1,lineup.length))}</b></div>${[['Ataque',lineup.filter(p=>['ATA','PD','PE','MEI'].includes(p.pos))],['Meio-campo',lineup.filter(p=>['VOL','MC','MEI'].includes(p.pos))],['Defesa',lineup.filter(p=>['ZAG','LD','LE','GOL'].includes(p.pos))]].map(([l,ps])=>{let val=Math.round(ps.reduce((a,p)=>a+p.ovr,0)/Math.max(ps.length,1));return `<div class="bar-row"><span>${l}</span><span class="bar"><i style="width:${val}%"></i></span><b>${val}</b></div>`}).join('')}</div><div style="margin-top:15px"><span class="tag">${lineup.length} titulares selecionados</span><span class="tag" style="margin-left:5px">${bench.length} reservas</span></div></div></div>`}
function openPlayer(id){let p=playerById(id);if(!p)return;modal={type:'player',id};render()}
function fixturesPage(){let matches=[];state.calendar.forEach((round,i)=>round.forEach(g=>matches.push({g,i})));let visible=matches.filter(({g,i})=>g.home===state.club||g.away===state.club);return `${header('Calendário',`${visible.filter(x=>x.g.played).length} de ${visible.length} partidas disputadas`)}<div class="card"><div class="card-head"><h2>Temporada ${state.season}</h2><span class="tag">${state.league.split('|')[1]}</span></div>${visible.map(({g,i})=>{let opp=opponentOf(g),mineHome=g.home===state.club;return `<div class="fixture"><div class="fixture-date">RODADA ${i+1}<br>${g.played?'FINALIZADO':i===state.round?'PRÓXIMA':'AGENDADO'}</div><div class="fixture-clubs">${mineHome?badge(currentClub(),'sm'):badge(opp,'sm')}<b>${mineHome?esc(currentClub().name):esc(opp.name)}</b><span style="color:#748174">×</span><b>${mineHome?esc(opp.name):esc(currentClub().name)}</b>${mineHome?badge(opp,'sm'):badge(currentClub(),'sm')}</div><span class="${g.played?'fixture-score':'tag'}">${g.played?`${g.score[0]} — ${g.score[1]}`:mineHome?'CASA':'FORA'}</span>${!g.played&&i===state.round?`<button class="btn btn-primary" onclick="playMatch()">JOGAR</button>`:''}</div>`}).join('')}</div>`}
function tablePage(){let sorted=rankTeams();return `${header('Classificação',`${state.league.split('|')[1]} · Temporada ${state.season}`)}<div class="card"><div class="card-head"><h2>Tabela do campeonato</h2><span class="tag green">${sorted.findIndex(t=>t.id===state.club)+1}º ${sorted.find(t=>t.id===state.club).name}</span></div>${leagueTable(sorted)}</div><div class="grid grid-3" style="margin-top:15px"><div class="stat-card"><div class="stat-label">LÍDER</div><div class="stat-value" style="font-size:17px">${esc(sorted[0].name)}</div><div class="stat-note good">${sorted[0].pts} pontos</div></div><div class="stat-card"><div class="stat-label">ARTILHEIRO DA LIGA</div>${leagueTopScorer()}</div><div class="stat-card"><div class="stat-label">MELHOR DEFESA</div><div class="stat-value" style="font-size:17px">${esc([...sorted].sort((a,b)=>a.ga-b.ga)[0].name)}</div><div class="stat-note">${[...sorted].sort((a,b)=>a.ga-b.ga)[0].ga} gols sofridos</div></div></div>`}
function leagueTopScorer(){let players=state.teams.flatMap(t=>t.players.map(p=>({...p,club:t.name}))).sort((a,b)=>b.goals-a.goals);return `<div class="stat-value" style="font-size:17px">${players[0]?.goals?esc(players[0].name):'—'}</div><div class="stat-note">${players[0]?.goals?players[0].goals+' gols · '+esc(players[0].club):'Gols após a primeira rodada'}</div>`}
function marketPage(){let list=state.available.filter(p=>marketTab==='all'||(marketTab==='free'?p.price<10000:p.pos===marketTab));return `${header('Transferências',`Orçamento disponível: ${money(state.budget)} · Negocie reforços para o elenco.`,`<button class="btn" onclick="openModal('finance')">FINANÇAS</button>`)}<div class="page-tabs"><button class="tab ${marketTab==='all'?'active':''}" onclick="marketTab='all';render()">Todos</button>${['GOL','ZAG','MC','MEI','ATA'].map(pos=>`<button class="tab ${marketTab===pos?'active':''}" onclick="marketTab='${pos}';render()">${pos}</button>`).join('')}<button class="tab ${marketTab==='free'?'active':''}" onclick="marketTab='free';render()">Oportunidades</button></div><div class="card"><div class="card-head"><h2>Mercado de jogadores</h2><span class="tag">${list.length} observados</span></div><div class="player-row header"><span>POS</span><span>JOGADOR</span><span>IDADE</span><span>GER</span><span>VALOR</span><span class="hide-mobile">CLUBE</span><span class="hide-mobile">AÇÃO</span></div>${list.slice(0,40).map(p=>`<div class="player-row"><span class="tag">${p.pos}</span><div><div class="player-name">${esc(p.name)}</div><div class="player-meta">Potencial ${p.potential} · ${p.age} anos</div></div><span>${p.age}</span><span class="rating">${p.ovr}</span><span>${money(p.price)}</span><span class="hide-mobile">${esc(p.club)}</span><button class="btn ${state.budget>=p.price?'btn-primary':''}" style="padding:6px 8px;font-size:9px" onclick="buyPlayer('${p.id}')">${state.budget>=p.price?'CONTRATAR':'SEM VERBA'}</button></div>`).join('')||'<div class="empty">Nenhum jogador disponível nesse filtro.</div>'}</div><p class="stat-note" style="margin:12px 4px">As negociações dependem do orçamento do clube. Jogadores gerados de forma procedural são fictícios e não representam elencos licenciados.</p>`}
function buyPlayer(id){let p=state.available.find(x=>x.id===id);if(!p)return;if(state.budget<p.price)return toast('Orçamento insuficiente para essa contratação.',true);if(state.roster.length>=25)return toast('Elenco cheio. Negocie uma saída antes de contratar.',true);let target=clubById(p.clubId);if(target){target.players=target.players.filter(x=>`m-${x.id}`!==id)}state.budget-=p.price;currentClub().budget=state.budget;state.roster.push({...p,id:p.id.replace('m-',''),apps:0,goals:0,starter:false});state.available=state.available.filter(x=>x.id!==id);state.manager.rep=Math.min(100,state.manager.rep+1);state.news.unshift({date:state.date,type:'transferência',title:`${p.name} é o novo reforço`,body:`O clube fechou a contratação do atleta por ${money(p.price)}.`});save();render();toast(`${p.name} contratado com sucesso!`)}
function inboxPage(){let messages=[...state.news.map(n=>({...n,kind:'notícia'})),...state.messages.map(m=>({...m,kind:'mensagem'}))].sort((a,b)=>b.date.localeCompare(a.date));return `${header('Central do clube','Notícias, mensagens da diretoria e acontecimentos da carreira.') }<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Caixa de entrada</h2><span class="tag">${messages.length} itens</span></div>${messages.map(m=>`<div class="inbox-item"><span class="news-kicker">${esc(m.kind)} · ${dateText(m.date)}</span><b>${esc(m.title)}</b><p>${esc(m.body)}</p>${m.action?`<button class="btn btn-primary" onclick="${m.action}">RESPONDER</button>`:''}</div>`).join('')||'<div class="empty"><div class="empty-icon">✉</div><h2>Tudo em dia</h2><p>As atualizações do seu clube aparecerão aqui.</p></div>'}</div><div class="card"><div class="card-head"><h2>Perfil do treinador</h2><span class="tag green">${esc(state.manager.experience)}</span></div><div style="display:flex;align-items:center;gap:12px;margin-bottom:19px"><div class="avatar" style="width:50px;height:50px;font-size:17px">${esc(initials(state.manager.name))}</div><div><b style="font-size:14px">${esc(state.manager.name)}</b><div class="stat-note">${esc(state.manager.nationality)} · ${state.manager.age} anos</div></div></div>${[['Reputação',state.manager.rep],['Popularidade',state.manager.popularity],['Licenças',state.manager.licenses*25]].map(([x,v])=>`<div class="bar-row" style="grid-template-columns:90px 1fr 30px"><span>${x}</span><span class="bar"><i style="width:${v}%"></i></span><b>${x==='Licenças'?state.manager.licenses:v}</b></div>`).join('')}<div class="settings-item"><div><b>Contrato atual</b><small>${state.contract.years} anos · salário ${money(state.contract.salary)}/semana</small></div><button class="btn" onclick="openModal('contract')">NEGOCIAR</button></div><div class="settings-item"><div><b>Objetivo da diretoria</b><small>${esc(state.objective)}</small></div></div><button class="btn btn-danger" style="margin-top:15px" onclick="resign()">PEDIR DEMISSÃO</button></div></div>`}
function statsPage(){let c=currentClub(),top=[...state.roster].sort((a,b)=>b.goals-a.goals)[0],apps=[...state.roster].sort((a,b)=>b.apps-a.apps)[0];return `${header('Estatísticas','Acompanhe os números da temporada e o seu legado.') }<div class="stats-row"><div class="stat-card"><div class="stat-label">JOGOS NA CARREIRA</div><div class="stat-value">${state.manager.wins+state.manager.draws+state.manager.losses}</div><div class="stat-note">${state.manager.wins}V · ${state.manager.draws}E · ${state.manager.losses}D</div></div><div class="stat-card"><div class="stat-label">TÍTULOS</div><div class="stat-value">${state.manager.titles}</div><div class="stat-note">Honrarias conquistadas</div></div><div class="stat-card"><div class="stat-label">VALOR DE MERCADO</div><div class="stat-value">${money(state.manager.rep*17500)}</div><div class="stat-note">Estimativa como treinador</div></div><div class="stat-card"><div class="stat-label">POPULARIDADE</div><div class="stat-value">${state.manager.popularity}%</div><div class="stat-note">Entre os torcedores</div></div></div><div class="grid grid-2"><div class="card"><div class="card-head"><h2>Desempenho do clube</h2><span class="tag">${esc(c.name)}</span></div><div class="bar-row"><span>Vitórias</span><span class="bar"><i style="width:${Math.min(100,c.w/Math.max(1,c.w+c.d+c.l)*100)}%"></i></span><b>${c.w}</b></div><div class="bar-row"><span>Empates</span><span class="bar"><i style="width:${Math.min(100,c.d/Math.max(1,c.w+c.d+c.l)*100)}%;background:var(--gold)"></i></span><b>${c.d}</b></div><div class="bar-row"><span>Derrotas</span><span class="bar"><i style="width:${Math.min(100,c.l/Math.max(1,c.w+c.d+c.l)*100)}%;background:var(--red)"></i></span><b>${c.l}</b></div><div class="settings-item"><div><b>Artilheiro do elenco</b><small>${esc(top?.name||'—')} · ${top?.goals||0} gols</small></div></div><div class="settings-item"><div><b>Mais utilizado</b><small>${esc(apps?.name||'—')} · ${apps?.apps||0} partidas</small></div></div></div><div class="card"><div class="card-head"><h2>Histórico da carreira</h2></div>${state.manager.history.length?state.manager.history.map(h=>`<div class="fixture"><span class="tag">${h.season}</span><div><b>${esc(h.club)}</b><div class="stat-note">${esc(h.competition)} · ${h.place}º lugar</div></div><b class="rating">${h.pts} pts</b></div>`).join(''):'<div class="empty" style="padding:28px"><div class="empty-icon">◷</div><h2>Comece sua jornada</h2><p>O histórico e os títulos aparecerão conforme você avança as temporadas.</p></div>'}</div></div>`}
function resign(){if(!confirm('Pedir demissão do clube? Você poderá escolher outro time, mas sua carreira continua.'))return;state.manager.history.push({season:state.season,club:currentClub().name,competition:state.league.split('|')[1],place:rankTeams().findIndex(t=>t.id===state.club)+1,pts:currentClub().pts});state.sacked=true;state.manager.club='Sem clube';state.messages.unshift({date:state.date,title:'Você pediu demissão',body:'A diretoria aceitou seu pedido. Escolha um novo clube para continuar a carreira.'});save();openModal('job');}
function editorPage(){return `${header('Editor de elencos','Ajuste os atributos dos atletas e salve sua base neste dispositivo.') }<div class="card"><div class="card-head"><h2>Editar elenco · ${esc(currentClub().name)}</h2><button class="btn btn-primary" onclick="save();toast('Elenco salvo no arquivo de carreira.')">SALVAR EDIÇÕES</button></div><div class="player-row header"><span>POS</span><span>JOGADOR</span><span>IDADE</span><span>GER</span><span>VALOR</span><span class="hide-mobile">POTENCIAL</span><span>EDITAR</span></div>${state.roster.map(p=>`<div class="player-row"><span class="tag">${p.pos}</span><div class="player-name">${esc(p.name)}</div><span>${p.age}</span><span class="rating">${p.ovr}</span><span>${money(p.value)}</span><span class="hide-mobile">${p.potential}</span><button class="btn" style="padding:6px 8px;font-size:9px" onclick="openPlayer('${p.id}')">EDITAR</button></div>`).join('')}</div>`}
function render(){let root=document.getElementById('app');if(!state){root.innerHTML=mainMenu()+(modal?modalHTML():'');return}let content=({dashboard,squad:squadPage,tactics:tacticsPage,fixtures:fixturesPage,table:tablePage,market:marketPage,inbox:inboxPage,stats:statsPage,editor:editorPage,settings:settingsPage})[route]||dashboard;root.innerHTML=`<div class="shell">${sideNav()}<main class="main">${topbar()}${content()}</main></div>${modal?modalHTML():''}`}
function mainMenu(){let saves=Object.entries(db.saves),last=saves.sort((a,b)=>b[1].updated.localeCompare(a[1].updated))[0];return `<div style="min-height:100vh;display:grid;place-items:center;padding:24px;position:relative;overflow:hidden"><div style="position:absolute;inset:0;background:radial-gradient(ellipse at 75% 30%,#2b442c 0,transparent 45%),linear-gradient(135deg,#0d1510,#14221a);opacity:.85"></div><div style="position:absolute;right:-5vw;bottom:-17vw;font-size:min(75vw,800px);opacity:.035;transform:rotate(-25deg)">⚽</div><div style="width:min(980px,100%);position:relative;z-index:1;display:grid;grid-template-columns:1.15fr .85fr;gap:46px;align-items:center"><div><div class="brand" style="padding:0 0 42px"><div class="brandmark" style="width:52px;height:52px;font-size:27px">⚽</div><div><strong style="font-size:23px">TOUCHLINE</strong><small>FOOTBALL CAREER MANAGER</small></div></div><div class="eyebrow">A SUA HISTÓRIA COMEÇA AQUI</div><h1 style="font:700 clamp(38px,6vw,65px)/1.02 var(--display);letter-spacing:-3px;margin:12px 0 18px">O futebol é<br><span style="color:var(--green)">feito de escolhas.</span></h1><p style="color:#a7b3a5;line-height:1.7;max-width:430px;font-size:14px">Crie seu legado à beira do campo. Monte o time, enfrente desafios e leve seu clube ao topo.</p><div style="display:flex;gap:13px;margin-top:27px;align-items:center"><span class="tag green">✦ CARREIRA PERSISTENTE</span><span class="tag">TEMPORADAS COMPLETAS</span></div><div style="margin-top:50px;color:#66746a;font-size:10px;letter-spacing:1px">TOUCHLINE FC · EDIÇÃO MANAGER 2026</div></div><div class="card" style="padding:25px;background:#172119f2;border-color:#354538;box-shadow:0 25px 100px #0006"><div class="eyebrow">MENU PRINCIPAL</div>${saves.length&&last?`<button class="btn btn-primary" style="width:100%;text-align:left;padding:14px;margin:8px 0 12px" onclick="loadSave('${esc(last[0])}')">▶ &nbsp; CONTINUAR CARREIRA <small style="float:right;font-weight:500">${esc(last[1].state.manager.name)}</small></button>`:''}<div style="display:grid;gap:8px">${[['new','✦','NOVA CARREIRA'],['load','▣','CARREGAR CARREIRA'],['settings','⚙','CONFIGURAÇÕES'],['editor','✎','EDITOR DE ELENCOS'],['stats','◫','ESTATÍSTICAS'],['credits','ⓘ','CRÉDITOS']].map(([a,i,l])=>`<button class="btn ${a==='new'?'btn-primary':''}" style="padding:13px 15px;text-align:left" onclick="menuAction('${a}')"><span style="display:inline-block;width:25px">${i}</span>${l}<span style="float:right;opacity:.5">→</span></button>`).join('')}</div><p class="stat-note" style="margin:15px 0 0;text-align:center">Jogo de gestão · Salvamento local automático</p></div></div></div>`}
function menuAction(action){if(action==='new')openModal('new');else if(action==='load')openModal('load');else if(action==='settings')openModal('settings');else if(action==='editor'||action==='stats'){if(!Object.keys(db.saves).length)return toast('Crie uma carreira primeiro.',true);if(!state){const key=Object.keys(db.saves)[0];loadSave(key)}route=action;render()}else if(action==='credits')openModal('credits')}
function loadSave(slot){let data=db.saves[slot];if(!data)return toast('Arquivo de carreira não encontrado.',true);activeSlot=slot;state=data.state;route='dashboard';modal=null;render();toast('Carreira carregada.')}
function showCareerMenu(){if(!confirm('Voltar ao menu principal? O progresso é salvo automaticamente.'))return;save();state=null;activeSlot=null;render()}
function settingsPage(){return `${header('Configurações','Personalize sua experiência de jogo.') }<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Preferências de jogo</h2></div><div class="settings-item"><div><b>Duração da partida</b><small>Define o ritmo da simulação</small></div><select style="background:#101812;color:white;border:1px solid #344235;padding:8px;border-radius:8px" onchange="db.settings.matchLength=+this.value;persist()"><option value="3" ${db.settings.matchLength===3?'selected':''}>Rápida · 3 min</option><option value="5" ${db.settings.matchLength===5||!db.settings.matchLength?'selected':''}>Normal · 5 min</option><option value="8" ${db.settings.matchLength===8?'selected':''}>Completa · 8 min</option></select></div><div class="settings-item"><div><b>Efeitos sonoros</b><small>Feedback de interface (sons a implementar)</small></div><button class="pill-toggle ${db.settings.sound?'active':''}" onclick="db.settings.sound=!db.settings.sound;persist();render()">${db.settings.sound?'ATIVADO':'DESATIVADO'}</button></div><div class="settings-item"><div><b>Privacidade dos dados</b><small>Carreiras ficam salvas apenas neste navegador.</small></div><span class="tag green">LOCAL</span></div></div><div class="card"><div class="card-head"><h2>Arquivos de carreira</h2></div><p class="stat-note" style="line-height:1.6">Você pode manter vários arquivos de carreira independentes. Os dados ficam no armazenamento local deste navegador; limpar os dados do navegador poderá apagá-los.</p><button class="btn" onclick="openModal('load')">GERENCIAR ARQUIVOS</button><button class="btn btn-danger" style="margin-left:7px" onclick="exportSave()">EXPORTAR ARQUIVO</button></div></div>`}
function exportSave(){if(!state)return;let blob=new Blob([JSON.stringify({state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`touchline-${state.manager.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}.json`;a.click();URL.revokeObjectURL(a.href);toast('Arquivo exportado.')}
function modalHTML(){let type=modal.type;let content='';if(type==='new')content=newCareerForm();else if(type==='load')content=loadForm();else if(type==='settings')content=settingsForm();else if(type==='credits')content=`<div class="modal-head"><div><h2>Créditos</h2><p>Obrigado por jogar Touchline.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="inbox-item"><b>TOUCHLINE · FOOTBALL CAREER MANAGER</b><p>Jogo independente de gestão esportiva. Clubes e competições apresentados são exemplos de referência; atletas são gerados proceduralmente e não são elencos licenciados. Nenhuma afiliação com ligas, federações ou clubes.</p></div><button class="btn btn-primary" onclick="closeModal()">VOLTAR</button>`;else if(type==='player')content=playerModal();else if(type==='finance')content=financeModal();else if(type==='contract')content=contractModal();else if(type==='job')content=jobModal();else if(type==='match')content=matchModal();return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal">${content}</div></div>`}
function closeModal(){modal=null;render()}
function newCareerForm(){let leagues=Object.keys(LEAGUES);return `<div class="modal-head"><div><div class="eyebrow">NOVA JORNADA</div><h2>Crie sua carreira</h2><p>Escolha seu perfil e assuma o comando.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form id="new-form" onsubmit="submitCareer(event)"><div class="form-grid"><div class="field"><label>NOME DO TREINADOR</label><input name="manager" required maxlength="30" placeholder="Ex.: Alex Costa" value="Alex Costa"></div><div class="field"><label>NACIONALIDADE</label><select name="nationality"><option>Brasil</option><option>Portugal</option><option>Argentina</option><option>Inglaterra</option><option>Espanha</option><option>Itália</option><option>França</option><option>Alemanha</option><option>Japão</option></select></div><div class="field"><label>IDADE</label><input name="age" type="number" min="18" max="80" value="38" required></div><div class="field"><label>APARÊNCIA</label><select name="appearance"><option>Clássico</option><option>Moderno</option><option>Jovem</option><option>Veterano</option></select></div><div class="field"><label>EXPERIÊNCIA</label><select name="experience"><option>Iniciante</option><option>Promissor</option><option>Experiente</option><option>Lenda</option></select></div><div class="field"><label>DIFICULDADE</label><select name="difficulty"><option>Normal</option><option>Desafio</option><option>Realista</option></select></div><div class="field"><label>PAÍS E DIVISÃO</label><select name="league" id="league-select" onchange="updateClubs()">${leagues.map(k=>`<option value="${esc(k)}">${esc(k.replace('|',' · '))}</option>`).join('')}</select><small>Banco expansível · ligas com clubes reais cadastrados</small></div><div class="field"><label>CLUBE INICIAL</label><select name="club" id="club-select">${LEAGUES[leagues[0]].clubs.map(c=>`<option>${esc(c[0])}</option>`).join('')}</select></div><div class="field"><label>REALISMO DAS NEGOCIAÇÕES</label><select name="realism"><option value="Realista">Realista</option><option value="Flexível">Flexível</option><option value="Rigoroso">Rigoroso</option></select></div><div class="field"><label>DURAÇÃO DA PARTIDA</label><select name="matchLength"><option value="3">Rápida · 3 minutos</option><option value="5" selected>Normal · 5 minutos</option><option value="8">Completa · 8 minutos</option></select></div></div><div class="modal-foot"><span class="stat-note">O progresso será salvo automaticamente.</span><button class="btn btn-primary" type="submit">COMEÇAR CARREIRA →</button></div></form>`}
function updateClubs(){let key=document.getElementById('league-select').value,sel=document.getElementById('club-select');sel.innerHTML=LEAGUES[key].clubs.map(c=>`<option>${esc(c[0])}</option>`).join('')}
function submitCareer(e){e.preventDefault();let form=Object.fromEntries(new FormData(e.target).entries()),slot=`career-${Date.now()}`;form.year=new Date().getFullYear();db.settings.matchLength=+form.matchLength;persist();startSave(form,slot)}
function loadForm(){let saves=Object.entries(db.saves);return `<div class="modal-head"><div><div class="eyebrow">GERENCIAR ARQUIVOS</div><h2>Carregar carreira</h2><p>Selecione um arquivo salvo neste dispositivo.</p></div><button class="modal-close" onclick="closeModal()">×</button></div>${saves.length?saves.sort((a,b)=>b[1].updated.localeCompare(a[1].updated)).map(([key,data])=>`<div class="inbox-item" style="display:flex;align-items:center;justify-content:space-between;gap:12px"><div><b>${esc(data.state.manager.name)}</b><p style="margin:5px 0 0">${esc(data.state.club?data.state.teams.find(t=>t.id===data.state.club)?.name:'Sem clube')} · Temporada ${data.state.season} · ${dateText(data.state.date)}</p></div><div style="display:flex;gap:6px"><button class="btn btn-primary" onclick="loadSave('${esc(key)}')">CARREGAR</button><button class="btn btn-danger" onclick="deleteSave('${esc(key)}')">✕</button></div></div>`).join(''):'<div class="empty"><div class="empty-icon">▣</div><h2>Nenhum arquivo salvo</h2><p>Inicie uma nova carreira para criar seu primeiro arquivo.</p></div>'}<div class="modal-foot"><button class="btn" onclick="closeModal()">FECHAR</button><button class="btn btn-primary" onclick="modal={type:'new'};render()">NOVA CARREIRA</button></div>`}
function deleteSave(k){if(confirm('Excluir este arquivo de carreira permanentemente?')){delete db.saves[k];persist();if(activeSlot===k){state=null;activeSlot=null}modal={type:'load'};render()}}
function settingsForm(){return `<div class="modal-head"><div><div class="eyebrow">PREFERÊNCIAS</div><h2>Configurações</h2><p>Defina o ritmo da partida e seus dados locais.</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="settings-item"><div><b>Duração da partida</b><small>Tempo sugerido para cada partida</small></div><select id="setting-length" style="background:#101812;color:white;border:1px solid #344235;padding:8px;border-radius:8px"><option value="3" ${db.settings.matchLength===3?'selected':''}>3 min</option><option value="5" ${db.settings.matchLength===5||!db.settings.matchLength?'selected':''}>5 min</option><option value="8" ${db.settings.matchLength===8?'selected':''}>8 min</option></select></div><div class="settings-item"><div><b>Efeitos sonoros</b><small>Feedback de interface</small></div><button class="pill-toggle ${db.settings.sound?'active':''}" onclick="db.settings.sound=!db.settings.sound;persist();modal={type:'settings'};render()">${db.settings.sound?'ATIVADO':'DESATIVADO'}</button></div><p class="stat-note" style="line-height:1.55">Dados salvos localmente neste navegador. Recomendamos exportar seu arquivo de carreira ocasionalmente.</p><div class="modal-foot"><button class="btn" onclick="closeModal()">CANCELAR</button><button class="btn btn-primary" onclick="db.settings.matchLength=+document.getElementById('setting-length').value;persist();closeModal();toast('Configurações salvas.')">SALVAR</button></div>`}
function openModal(type){modal={type};render()}
function matchPlayers(team){return team.id===state.club?state.roster:team.players}
function recordScorers(team,goals,minuteOffset=0){let players=matchPlayers(team),available=players.filter(p=>team.id!==state.club||state.lineup.includes(p.id));if(!available.length)available=players.slice(0,11);let events=[];for(let i=0;i<goals;i++){let p=available[Math.floor(Math.random()*available.length)];if(p){p.goals=(p.goals||0)+1;events.push({minute:Math.min(90,Math.floor(7+Math.random()*83)),player:p.name,club:team.short})}}return events.sort((a,b)=>a.minute-b.minute)}
function recordAppearance(team){let players=matchPlayers(team),chosen=team.id===state.club?players.filter(p=>state.lineup.includes(p.id)):players.slice(0,11);if(chosen.length<7)chosen=players.slice(0,11);chosen.forEach(p=>p.apps=(p.apps||0)+1);if(team.id===state.club)players.forEach(p=>p.fitness=Math.max(35,(p.fitness||90)-Math.round(7+Math.random()*8)));else chosen.forEach(p=>p.fitness=Math.max(35,(p.fitness||90)-10))}
function playMatch(){if(!state||modal?.type==='match')return;let game=nextGame();if(!game){if(state.round>=state.calendar.length)return toast('A temporada terminou. Inicie a próxima temporada.',true);return toast('Não foi possível localizar a próxima partida.',true)}let home=clubById(game.home),away=clubById(game.away),playerHome=home.id===state.club,[h,a]=simScore(home,away);applyResult(game,h,a);let allGames=state.calendar[state.round];allGames.forEach(g=>{if(g===game)return;let ht=clubById(g.home),at=clubById(g.away),score=simScore(ht,at);applyResult(g,score[0],score[1]);recordAppearance(ht);recordAppearance(at);recordScorers(ht,score[0]);recordScorers(at,score[1])});recordAppearance(home);recordAppearance(away);let homeEvents=recordScorers(home,h),awayEvents=recordScorers(away,a);matchLog=[...homeEvents.map(e=>`${e.minute}′ — GOL ${e.club}: ${e.player}`),...awayEvents.map(e=>`${e.minute}′ — GOL ${e.club}: ${e.player}`)].sort((x,y)=>parseInt(x)-parseInt(y));let own=playerHome?h:a,opp=playerHome?a:h;if(own>opp){state.manager.wins++;state.manager.popularity=Math.min(100,state.manager.popularity+2);state.manager.rep=Math.min(100,state.manager.rep+1)}else if(own===opp){state.manager.draws++;state.manager.popularity=Math.min(100,state.manager.popularity+1)}else{state.manager.losses++;state.manager.popularity=Math.max(0,state.manager.popularity-2)}let attendance=Math.round(home.capacity*(.62+Math.random()*.32)),revenue=attendance*12;state.budget+=revenue;currentClub().budget=state.budget;state.lastMatch={home:home.id,away:away.id,score:[h,a],round:state.round+1,attendance,revenue,events:matchLog.slice()};state.news.unshift({date:state.date,type:'partida',title:`${home.name} ${h} × ${a} ${away.name}`,body:`Rodada ${state.round+1} da ${state.league.split('|')[1]}. ${home.id===state.club?`Renda de ${money(revenue)} com ${attendance.toLocaleString('pt-BR')} torcedores.`:'Partida concluída.'}`});state.round++;state.matchday=state.round+1;addDays(7);state.teams.forEach(t=>t.players.forEach(p=>{p.form=Math.max(4,Math.min(10,Math.round((p.form||6)+(Math.random()-.45))))}));save();modal={type:'match'};render()}
function matchModal(){let m=state.lastMatch;if(!m)return '<p>Partida indisponível.</p>';let h=clubById(m.home),a=clubById(m.away);return `<div class="modal-head"><div><div class="eyebrow">FIM DE JOGO · RODADA ${m.round}</div><h2>Apito final</h2><p>${esc(state.league.split('|')[1])} · ${dateText()}</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="scoreboard"><div>${badge(h)}<b>${esc(h.name)}</b></div><span class="score">${m.score[0]} <i>—</i> ${m.score[1]}</span><div>${badge(a)}<b>${esc(a.name)}</b></div></div><div class="card-head"><h2>Principais momentos</h2><span class="tag">${m.attendance.toLocaleString('pt-BR')} torcedores</span></div><div class="event-list">${m.events.length?m.events.map(x=>`<div class="inbox-item" style="padding:9px 0"><b>${esc(x)}</b></div>`).join(''):'<p class="stat-note">Jogo sem gols. As defesas levaram a melhor.</p>'}</div><p class="stat-note">Renda da partida: ${money(m.revenue)} · Próxima rodada em ${dateText(state.date)}.</p><div class="modal-foot"><button class="btn" onclick="setRoute('table')">VER CLASSIFICAÇÃO</button><button class="btn btn-primary" onclick="closeModal()">CONTINUAR →</button></div>`}
function advanceSeason(){if(state.round<state.calendar.length)return toast('Conclua todas as rodadas antes de iniciar uma nova temporada.',true);let champ=rankTeams()[0],mine=rankTeams().findIndex(t=>t.id===state.club)+1,oldSeason=state.season;state.manager.history.push({season:oldSeason,club:currentClub().name,competition:state.league.split('|')[1],place:mine,pts:currentClub().pts});if(champ.id===state.club){state.manager.titles++;state.manager.rep=Math.min(100,state.manager.rep+5);state.manager.popularity=Math.min(100,state.manager.popularity+12);state.news.unshift({date:state.date,type:'título',title:`${currentClub().name} é campeão!`,body:`O clube conquistou ${state.league.split('|')[1]} na temporada ${oldSeason}.`})}else{state.manager.rep=Math.max(1,state.manager.rep+(mine<=3?3:mine>=state.teams.length-2?-2:0));state.news.unshift({date:state.date,type:'temporada',title:`Temporada ${oldSeason} concluída`,body:`${currentClub().name} terminou em ${mine}º lugar com ${currentClub().pts} pontos.`})}state.roster.forEach(p=>{p.age++;if(p.age<30&&p.ovr<p.potential&&Math.random()<.58)p.ovr++;else if(p.age>32&&Math.random()<.45)p.ovr=Math.max(45,p.ovr-1);p.value=Math.round(p.ovr*p.ovr*120*(p.age<22?1.35:p.age>31?.65:1));p.fitness=100;p.form=6;p.apps=0;p.goals=0});state.teams.forEach(t=>{t.pts=t.w=t.d=t.l=t.gf=t.ga=0;t.form=[];if(t.id!==state.club)t.players.forEach(p=>{p.age++;if(p.age<30&&p.ovr<p.potential&&Math.random()<.45)p.ovr++;else if(p.age>32&&Math.random()<.4)p.ovr=Math.max(45,p.ovr-1);p.apps=0;p.goals=0;p.fitness=100})});currentClub().players=state.roster;state.season++;state.date=`${state.season}-07-01`;state.calendar=schedule();state.round=0;state.matchday=1;state.available=makeMarket(state.teams);state.budget+=Math.round(currentClub().rep*currentClub().rep*500);currentClub().budget=state.budget;state.contract.years=Math.max(0,state.contract.years-1);state.news.unshift({date:state.date,type:'temporada',title:`Temporada ${state.season} começou`,body:`A pré-temporada está aberta. Objetivo da diretoria: ${state.objective}.`});save();route='dashboard';modal=null;render();toast(`Temporada ${state.season} iniciada.`)}
function playerModal(){let p=playerById(modal.id);if(!p)return '<p>Atleta não encontrado.</p>';let editing=route==='editor';return `<div class="modal-head"><div><div class="eyebrow">${editing?'EDITOR DE ELENCOS':'PERFIL DO ATLETA'}</div><h2>${esc(p.name)}</h2><p>${p.pos} · ${p.age} anos · ${p.apps} partidas · ${p.goals} gols</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="stats-row"><div class="stat-card"><div class="stat-label">GER</div><div class="stat-value">${p.ovr}</div></div><div class="stat-card"><div class="stat-label">POTENCIAL</div><div class="stat-value">${p.potential}</div></div><div class="stat-card"><div class="stat-label">VALOR</div><div class="stat-value" style="font-size:17px">${money(p.value)}</div></div></div>${editing?`<div class="form-grid"><div class="field"><label>NOME</label><input id="edit-name" maxlength="40" value="${esc(p.name)}"></div><div class="field"><label>POSIÇÃO</label><select id="edit-pos">${['GOL','ZAG','LD','LE','VOL','MC','MEI','PD','PE','ATA'].map(x=>`<option ${p.pos===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>IDADE</label><input id="edit-age" type="number" min="16" max="45" value="${p.age}"></div><div class="field"><label>GERAL</label><input id="edit-ovr" type="number" min="40" max="99" value="${p.ovr}"></div><div class="field"><label>POTENCIAL</label><input id="edit-pot" type="number" min="40" max="99" value="${p.potential}"></div></div>`:`<div class="settings-item"><div><b>Condição física</b><small>${p.fitness||90}% · Forma ${p.form||6}/10</small></div><span class="bar"><i style="width:${p.fitness||90}%"></i></span></div><div class="settings-item"><div><b>Salário semanal</b><small>${money(p.wage)}</small></div><span class="tag">${state.lineup.includes(p.id)?'TITULAR':'RESERVA'}</span></div>`}<div class="modal-foot"><button class="btn" onclick="closeModal()">FECHAR</button>${editing?`<button class="btn btn-primary" onclick="savePlayerEdit('${p.id}')">SALVAR ALTERAÇÕES</button>`:`<button class="btn btn-primary" onclick="closeModal();setRoute('squad')">VER ELENCO</button>`}</div>`}
