const targets=await (await fetch('http://localhost:9222/json/list')).json();
const target=targets.find(t=>t.type==='page'&&t.url==='about:blank');
const ws=new WebSocket(target.webSocketDebuggerUrl);
let seq=0; const pending=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
function call(method,params={}){return new Promise(resolve=>{const id=++seq;pending.set(id,resolve);ws.send(JSON.stringify({id,method,params}))})}
async function evalJS(expression){const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.error||r.result?.exceptionDetails)throw Error(JSON.stringify(r));return r.result.result.value}
await call('Page.enable');
await call('Page.navigate',{url:'file:///home/runner/work/PlayGround/PlayGround/index.html'});
await new Promise(resolve=>setTimeout(resolve,1500));
const menu=await evalJS("document.querySelector('#app').innerText");
console.log('default lang',await evalJS('document.documentElement.lang'),'default Portuguese',menu.includes('A SUA HISTÓRIA COMEÇA AQUI'));
await evalJS("openModal('settings')");
await evalJS("document.querySelector('#setting-language').value='en';setLanguage('en')");
console.log('modal English',await evalJS("document.documentElement.lang+'|'+document.querySelector('#app').innerText.includes('Game preferences')+'|'+localStorage.getItem('touchline-careers-v1')"));
await evalJS("openModal('new')");
console.log('new career English',await evalJS("document.querySelector('#app').innerText.includes('Start a career')+'|'+document.querySelector('#new-form')?.innerText.includes('DIFFICULTY')"));
await evalJS("setLanguage('es')");
console.log('new career Spanish',await evalJS("document.documentElement.lang+'|'+document.querySelector('#app').innerText.includes('Crea tu carrera')"));
await evalJS("setLanguage('pt')");
console.log('new career Portuguese',await evalJS("document.documentElement.lang+'|'+document.querySelector('#app').innerText.includes('Crie sua carreira')"));
ws.close();

