 function tr(text){let lang=db.settings?.language||'pt',dict=TRANSLATIONS[lang];if(!dict||lang==='pt')return text;return Object.entries(dict).sort((a,b)=>b[0].length-a[0].length).reduce((out,[from,to])=>out.replaceAll(from,to),String(text))}
 function translateMarkup(html){let lang=db.settings?.language||'pt';document.documentElement.lang=lang==='es'?'es':lang==='en'?'en':'pt-BR';if(lang==='pt')return html;let template=document.createElement('template');template.innerHTML=html;let walker=document.createTreeWalker(template.content,NodeFilter.SHOW_TEXT);while(walker.nextNode())walker.currentNode.textContent=tr(walker.currentNode.textContent);template.content.querySelectorAll('[aria-label],[placeholder],[title]').forEach(el=>['aria-label','placeholder','title'].forEach(attr=>{if(el.hasAttribute(attr))el.setAttribute(attr,tr(el.getAttribute(attr)))}));return template.innerHTML}
 function loadDB(){try{let stored=JSON.parse(localStorage.getItem(KEY))||{},settings={sound:true,matchLength:5,language:'pt',...(stored.settings||{})};if(!['pt','en','es'].includes(settings.language))settings.language='pt';return{...stored,saves:stored.saves||{},settings}}catch{return{saves:{},settings:{sound:true,matchLength:5,language:'pt'}}}}

